(async function(){
  'use strict';
  const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const url=s=>{try{const u=new URL(s,document.baseURI);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
  const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  const fmt=n=>Number(n).toLocaleString('fr-CA',{maximumFractionDigits:3});
  const labels={horizontal:'Pose horizontale',vertical:'Pose verticale',panel:'Panneaux',lap:'Clins',shingle:'Bardeaux',brick:'Maçonnerie'};
  let materials=[];
  try{const r=await fetch('catalogue-fd6866b49d21.json');if(!r.ok)throw Error();materials=(await r.json()).materials;}catch{$('#brand-title').textContent='Catalogue indisponible';$('#brand-note').textContent='Rechargez la page pour réessayer.';return;}
  const brands=[...new Set(materials.filter(m=>m.brand&&!m.id.startsWith('generic-')).map(m=>m.brand))];
  const preferred=['James Hardie','Maibec','CanExel','St-Laurent','Kaycan','Gentek','Allura','LP','Rialux','MAC','Royal','Juste du Pin','Light Trim','Vicwest','Adfast'];
  brands.sort((a,b)=>{const rank=x=>{const n=preferred.findIndex(y=>norm(x).includes(norm(y)));return n<0?99:n;};return rank(a)-rank(b)||a.localeCompare(b,'fr');});
  const requested=new URLSearchParams(location.search).get('marque');let brand=brands.find(b=>requested&&norm(b).includes(norm(requested)))||brands[0];
  function colorSwatch(c,cls='mini-swatch'){const hex=/^#[0-9a-f]{6}$/i.test(c.hex||'')?c.hex:null;return `<span class="${cls}"${hex?` style="background:${hex}"`:''}>${c.swatchUrl?`<img src="${esc(url(c.swatchUrl))}" alt="" loading="lazy">`:''}</span>`;}
  function diagram(m){const pattern=m.renderPattern;if(pattern==='panel')return '<path d="M3 3h48v34H3zM27 3v34M3 20h48"/>';if(pattern==='shingle')return '<path d="M3 8h48M3 19h48M3 30h48M12 8v11M30 8v11M42 8v11M21 19v11M39 19v11"/>';if(pattern==='vertical')return '<path d="M5 3v34M16 3v34M27 3v34M38 3v34M49 3v34"/>';if((m.applications||[]).some(a=>['opening-trim','band','fascia','bending'].includes(a)))return '<path d="M8 3v29h40M20 3v18h28"/>';return '<path d="M3 7h48M3 16h48M3 25h48M3 34h48"/>';}
  function specs(m){const d=m.dimensions||{},a=[];if(m.formats?.length>1)a.push(m.formats.map(f=>f.label||(f.widthIn?`${fmt(f.widthIn/12)} × ${fmt(f.lengthIn/12)} pi`:`${fmt(f.lengthIn)} po`)).join(' / '));if(d.widthIn)a.push(`${fmt(d.widthIn)} po`);if(d.lengthFt)a.push(`${fmt(d.lengthFt)} pi`);if(m.coverage?.exposureIn)a.push(`${fmt(m.coverage.exposureIn)} po visibles`);for(const o of m.allowedOrientations||[])a.push(labels[o]||o);return a.slice(0,4);}
  function filtered(){const q=norm($('#product-search').value),app=$('#application-filter').value;return materials.filter(m=>m.brand===brand&&(!q||norm([m.name,m.family,m.description].join(' ')).includes(q))&&(app==='all'||(app==='opening-trim'?(m.applications||[]).some(a=>['opening-trim','band'].includes(a)):app==='accessories'?(m.applications||[]).some(a=>['accessory','fastener','sealant','trim','accessories','fasteners'].includes(a)):(m.applications||[]).includes(app))));}
  function render(){
    $('#brand-buttons').innerHTML=brands.map(b=>`<button class="${b===brand?'active':''}" aria-pressed="${b===brand}" data-brand="${esc(b)}">${esc(b)} <small>${materials.filter(m=>m.brand===b).length}</small></button>`).join('');
    $('#brand-title').textContent=brand;const list=filtered().sort(window.MIRCatalogueOrder.compare);$('#product-count').textContent=`${list.length} référence${list.length===1?'':'s'}`;
    $('#brand-note').textContent='Sélection documentée. Les options varient selon le profil, le fini et la région.';
    $('#catalogue-empty').hidden=!!list.length;
    let previousSection=null;$('#product-list').innerHTML=list.map(m=>{const photo=m.images?.find(x=>x.src===m.primaryImage)||m.images?.[0];const colors=(m.colors||[]).filter(c=>c&&c.name);const section=window.MIRCatalogueOrder.section(m),heading=previousSection===section?'':`<h3 class="catalogue-group-heading">${esc(window.MIRCatalogueOrder.sections.find(x=>x[0]===section)?.[1]||'Produits')}</h3>`;previousSection=section;return `${heading}<article class="product-card">${photo?.src?`<a class="catalogue-product-photo" href="produit.html?id=${encodeURIComponent(m.id)}"><img src="${esc(url(photo.src))}" alt="${esc(photo.alt||m.name)}" loading="lazy"></a>`:''}<div class="product-meta"><span>${esc(m.family||m.brand)}</span><svg class="profile-diagram" viewBox="0 0 54 40" fill="none" stroke="#78906c" stroke-width="1.5" aria-hidden="true">${diagram(m)}</svg></div><h3>${esc(m.name)}</h3><div class="product-specs">${specs(m).map(s=>`<span>${esc(s)}</span>`).join('')}</div><p class="product-description">${esc(m.description||'Consultez les dimensions et les documents de cette référence.')}</p><div class="color-strip">${colors.slice(0,7).map(c=>colorSwatch(c)).join('')}<small>${colors.length?`${colors.length} couleurs documentées`:'Nuancier à documenter'}</small></div><div class="product-actions"><a href="produit.html?id=${encodeURIComponent(m.id)}">Ouvrir la fiche produit ↗</a><button data-material="${esc(m.id)}">Couleurs et documents</button>${(m.applications||[]).includes('siding')?`<a href="plan.html?material=${encodeURIComponent(m.id)}">Sur le plan →</a>`:''}</div></article>`;}).join('');
    $('#brand-buttons').querySelectorAll('button').forEach(b=>b.onclick=()=>{brand=b.dataset.brand;$('#product-search').value='';$('#application-filter').value='all';history.replaceState(null,'',`materiaux.html?marque=${encodeURIComponent(brand)}`);render();});
    $('#product-list').querySelectorAll('[data-material]').forEach(b=>b.onclick=()=>showMaterial(b.dataset.material));
  }
  function showMaterial(id){
    const m=materials.find(x=>x.id===id);if(!m)return;$('#material-brand').textContent=m.brand;$('#material-title').textContent=m.name;
    const d=m.dimensions||{},dimensions=[];
    for(const [key,label,unit] of [['widthIn','Largeur totale','po'],['lengthFt','Longueur','pi'],['lengthIn','Longueur','po'],['thicknessIn','Épaisseur','po']])if(Number.isFinite(d[key]))dimensions.push([label,`${fmt(d[key])} ${unit}`]);
    if(m.coverage?.exposureIn)dimensions.push(['Largeur visible',`${fmt(m.coverage.exposureIn)} po`]);
    if(m.allowedOrientations?.length)dimensions.push(['Sens de pose',m.allowedOrientations.map(o=>labels[o]||o).join(' · ')]);
    const colors=(m.colors||[]).filter(c=>c&&c.name),docs=m.documents||[],notes=(m.notes||[]).filter(n=>typeof n==='string');
    $('#material-body').innerHTML=`<p>${esc(m.description)}</p>${dimensions.length?`<section class="material-section"><h3>Dimensions et pose</h3><dl class="material-dimensions">${dimensions.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl></section>`:''}<section class="material-section"><h3>Couleurs ${esc(m.brand)}</h3>${colors.length?`<div class="official-colors">${colors.map(c=>`<a class="official-color" href="produit.html?id=${encodeURIComponent(m.id)}&color=${encodeURIComponent(c.id)}">${colorSwatch(c,'swatch')}<b>${esc(c.name)}</b>${c.collection?`<small>${esc(c.collection)}</small>`:''}${!c.hex&&!c.swatchUrl?'<small>Nom vérifié · aperçu à venir</small>':''}</a>`).join('')}</div><p class="document-note">Teintes du nuancier documenté; la disponibilité du fini et de la couleur pour cette référence reste à confirmer. L’écran ne remplace pas l’échantillon physique.</p>`:'<p class="document-note">Aucune teinte non vérifiée n’est ajoutée à cette référence. Consultez le nuancier officiel ci-dessous.</p>'}<a class="source-link" href="${esc(url(colors[0]?.sourceUrl||m.colorSourceUrl||m.sourceUrl))}" target="_blank" rel="noopener">Consulter le fabricant ↗</a></section><section class="material-section"><h3>Documentation</h3><div class="material-documents">${docs.map(doc=>`<a href="${esc(url(doc.url))}" target="_blank" rel="noopener"><span>${esc(doc.title||'Documentation fabricant')}<small>${doc.scope==='resource-center'?'Centre de documentation · sélectionner la référence':doc.scope==='system'?'Document de gamme / système':'Document fabricant'}${doc.verified?'':' · référence à vérifier'}</small></span><span>↗</span></a>`).join('')||'<p class="document-note">Documents propres à cette référence à compléter.</p>'}</div>${docs.some(doc=>doc.note)?`<p class="document-note">${docs.filter(doc=>doc.note).map(doc=>esc(doc.note)).join(' ')}</p>`:''}</section>${notes.length?`<section class="material-section"><h3>À savoir sur cette référence</h3><ul class="material-notes">${notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></section>`:''}<div class="material-action-row">${(m.applications||[]).includes('siding')?`<a class="mir-button" href="plan.html?material=${encodeURIComponent(m.id)}">Essayer ce profil sur le plan ↗</a>`:''}<a class="quiet-button" href="${esc(url(m.sourceUrl))}" target="_blank" rel="noopener">Fiche officielle ↗</a></div>`;
    $('#material-dialog').showModal();$('#material-dialog').scrollTop=0;
  }
  $('#material-close').onclick=()=>$('#material-dialog').close();
  $('#material-dialog').onclick=e=>{if(e.target===$('#material-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
  $('#product-search').addEventListener('input',render);$('#application-filter').addEventListener('change',render);render();
})();
